pm.test("API-001 - HTTP status is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("API-001 - Response code is 200", function () {
    const response = pm.response.json();
    pm.expect(response.responseCode).to.eql(200);
});

pm.test("API-001 - Products list is not empty", function () {
    const response = pm.response.json();
    pm.expect(response.products).to.be.an("array");
    pm.expect(response.products.length).to.be.above(0);
});

pm.test("API-001 - Products have required fields", function () {
    const response = pm.response.json();

    response.products.forEach(function (product) {
        pm.expect(product).to.have.property("id");
        pm.expect(product).to.have.property("name");
        pm.expect(product).to.have.property("price");
        pm.expect(product).to.have.property("brand");
    });
});

